import { Node } from 'cleo'

/**
 * Valley — turns a windmill's sails. Attach to the `Sails` node, whose origin is the hub and whose local
 * X is the axle (the Valley example builds them that way). Pure decoration: no physics, no gameplay.
 *
 * With `followWind` the sails turn with the scene's Wind: `degreesPerSecond` at its usual strength (1),
 * twice as fast in a storm (2), and never slower than a fifth of it however calm, so a sequence building
 * a storm (the Valley Tour's wind presets) speeds the sails up with the grass and the clouds.
 */
export default class ValleyWindmillNode extends Node {
  /** Sail speed in degrees per second at the wind's usual strength; negative turns the other way. */
  public degreesPerSecond: number = 24
  /** Turn faster in a stronger wind (the scene's Wind node), slower in a weaker one. */
  public followWind: boolean = true

  onUpdate(delta: number) {
    const wind: any = this.followWind ? (this.scene as any)?.wind : null
    const strength = wind && wind.visible !== false ? Math.max(0.2, Number(wind.strength) || 0) : 1
    this.rotateX(this.degreesPerSecond * strength * delta)
    // Keep the angle small so it never loses precision over a long session.
    if (Math.abs(this.rotation[0]) > 360) this.setRotation([this.rotation[0] % 360, this.rotation[1], this.rotation[2]])
  }
}

import { Node } from 'cleo'

/**
 * Valley — a fire's light: torches, braziers, fire pits, candles, the bonfire. Attach to the fire's root;
 * it finds its parts by type, so any layout works:
 *
 *   Torch                 this script
 *   ├── Flame             animated sprite(s), following the Light
 *   ├── Ignition          optional: an animated sprite played ONCE as the fire is lit (the bonfire's)
 *   ├── Embers            particle system(s), following the Light
 *   └── Light             point light, flickering
 *
 * - FLICKER is the engine's, not this script's: the light's own Flicker (PunctualLight.flickerAmount)
 *   wanders its intensity, and the flames and embers burn on the same beat through their Follow Light.
 *   Intensity only, so a shadowed torch keeps its cached shadow map.
 * - NO DAY AND NIGHT. The light keeps its real lumens around the clock; the camera's auto exposure is what
 *   makes it vanish in sunlight and carry the road at night.
 *
 * `lit` puts the fire out and lights it again: flames hidden, embers stopped, light off. The bonfire's
 * script drives it (its `Fire` child is one of these), so an unlit bonfire is a cold one.
 *
 * LIGHTING IT, when the fire has an `Ignition` sprite (a non-looping flipbook of the fire catching, baked
 * with the FX Creator): the ignition plays from its first frame, the light flares up with it and settles,
 * the embers start at once, the smoke thickens over the whole of it, and the burning flames fade in over
 * its last `ignitionBlend` seconds while the ignition fades out, so the flare settles into the loop. A
 * fire that STARTS lit (a torch, a bonfire already lit when the scene opens) just burns.
 */
export default class ValleyFireLightNode extends Node {
  /** Burning or not. */
  public lit: boolean = true
  /** Seconds, at the end of the ignition, over which the burning flames take over from it. */
  public ignitionBlend: number = 0.5
  /** The light's peak as the fire catches, over its full intensity. */
  public ignitionFlare: number = 1.4
  /** Seconds into the ignition the flare peaks. */
  public ignitionFlareTime: number = 0.25

  private _lights: { node: any, intensity: number }[] = []
  private _visuals: any[] = []
  private _sprites: { node: any, opacity: number, smoke: boolean }[] = []
  private _ignition: any = null
  private _shown: boolean = true
  /** Seconds into the ignition, or -1 when none is playing. */
  private _igniting: number = -1
  private _ignitionLength: number = 0

  onStart() {
    const walk = (n: any) => {
      const type = n.nodeType
      if (type === 'light' && n.light) this._lights.push({ node: n, intensity: n.light.intensity })
      else if (type === 'animatedSprite' && n.name === 'Ignition') this._ignition = n
      else if (type === 'sprite' || type === 'animatedSprite' || type === 'particleSystem') {
        this._visuals.push(n)
        if (n.sprite) this._sprites.push({ node: n, opacity: n.sprite.opacity, smoke: n.name === 'Smoke' })
      }
      for (const c of n.children ?? []) walk(c)
    }
    for (const c of this.children) walk(c)
    if (this._ignition) {
      this._ignition.visible = false
      const frames = this._ignition.frames?.length ?? 0
      this._ignitionLength = frames > 0 ? frames / Math.max(1e-3, this._ignition.fps ?? 30) : 0
    }
  }

  onUpdate(delta: number) {
    if (this.lit !== this._shown) {
      // Lit from out: the fire catches. Put out, or lit with no ignition sprite: it just changes.
      const catches = this.lit && !this._shown && this._ignition && this._ignitionLength > 0
      this._show(this.lit)
      if (catches) this._ignite()
      else this._endIgnition()
    }
    if (this._igniting >= 0) this._stepIgnition(delta)
  }

  private _show(lit: boolean): void {
    this._shown = lit
    for (const l of this._lights) l.node.light.intensity = lit ? l.intensity : 0
    for (const node of this._visuals) {
      if (node.nodeType === 'particleSystem') { if (lit) node.play?.(); else node.stop?.(true) }
      else node.visible = lit
    }
  }

  private _ignite(): void {
    this._igniting = 0
    const ignition = this._ignition
    ignition.reset?.()
    ignition.currentFrame = 0
    ignition.sprite.opacity = 1
    ignition.visible = true
    this._stepIgnition(0)
  }

  private _stepIgnition(delta: number): void {
    const t = (this._igniting += delta)
    const length = this._ignitionLength
    if (t >= length) { this._endIgnition(); return }
    // The burning flames take over across the last `ignitionBlend` seconds; the smoke builds all along.
    const blend = Math.min(Math.max(0.05, this.ignitionBlend), length)
    const handover = Math.min(1, Math.max(0, (t - (length - blend)) / blend))
    const build = t / length
    for (const s of this._sprites) s.node.sprite.opacity = s.opacity * (s.smoke ? build : handover)
    this._ignition.sprite.opacity = 1 - handover
    // The light: up to the flare at `ignitionFlareTime`, then down to its full intensity by the end.
    const peak = Math.max(1e-3, Math.min(this.ignitionFlareTime, length * 0.5))
    const scale = t < peak
      ? this.ignitionFlare * smooth(t / peak)
      : 1 + (this.ignitionFlare - 1) * (1 - smooth((t - peak) / Math.max(1e-3, length - peak)))
    for (const l of this._lights) l.node.light.intensity = l.intensity * scale
  }

  /** The ignition over (or cut short): the fire as it burns, the ignition hidden for next time. */
  private _endIgnition(): void {
    if (this._igniting < 0) return
    this._igniting = -1
    for (const s of this._sprites) s.node.sprite.opacity = s.opacity
    if (this._ignition) this._ignition.visible = false
    if (this._shown) for (const l of this._lights) l.node.light.intensity = l.intensity
  }
}

/** Smoothstep on 0..1. */
function smooth(x: number): number {
  const t = Math.min(1, Math.max(0, x))
  return t * t * (3 - 2 * t)
}

import { CameraRigNode, Input } from 'cleo'

/**
 * Valley — a free-flying camera for looking round the scenery in Play. Attach to a Camera Rig with a
 * Camera child. The rig follows nothing and has no arm, so its own position is the eye; this script moves
 * it and turns its aim.
 *
 *   Move        W A S D / left stick         along the view, so looking down and pressing W dives
 *   Look        mouse (click to capture) or left-drag / right stick
 *   Ascend      Space or E / right bumper    straight up, whatever the view
 *   Descend     C or Q / left bumper
 *   Sprint      Shift / left stick press     `sprintScale` times faster
 *   Fly Speed   mouse wheel                  steps the cruising speed between `minSpeed` and `maxSpeed`
 *
 * The camera eases into and out of motion (`smoothing`) and never goes below the landscape plus
 * `groundClearance`, so it skims the ground rather than diving under it.
 */
export default class ValleyFlyCameraNode extends CameraRigNode {
  /** Cruising speed, metres per second. */
  public speed: number = 8
  /** Slowest and fastest cruising speed the wheel can set. */
  public minSpeed: number = 1
  public maxSpeed: number = 80
  /** Multiplier while Sprint is held. */
  public sprintScale: number = 4
  /** Seconds to reach the speed being asked for. 0 is instant. */
  public smoothing: number = 0.15
  /** Metres kept between the eye and the landscape below. */
  public groundClearance: number = 1.2

  private _velocity: number[] = [0, 0, 0]

  onUpdate(delta: number) {
    if (delta <= 0) return
    // A mouse delta is already per frame; a stick is a held rate, scaled to feel the same at any frame rate.
    const look = Input.vector('Look')
    const k = Input.device('Look') === 'gamepadAxis' ? delta * 60 : 1
    if (look[0] !== 0 || look[1] !== 0) {
      this.addYaw(-look[0] * k)
      this.addPitch(look[1] * k)
    }

    const wheel = Input.value('Fly Speed')
    if (wheel !== 0) this.speed = Math.min(this.maxSpeed, Math.max(this.minSpeed, this.speed * (wheel < 0 ? 1.2 : 1 / 1.2)))

    // The view direction (yaw counter-clockwise from +Z, pitch positive looking down) and its right, -X at yaw 0.
    const yaw = this.yaw * Math.PI / 180, pitch = this.pitch * Math.PI / 180
    const cp = Math.cos(pitch)
    const fx = Math.sin(yaw) * cp, fy = -Math.sin(pitch), fz = Math.cos(yaw) * cp
    const rx = -Math.cos(yaw), rz = Math.sin(yaw)

    const move = Input.vector('Move')
    const lift = (Input.pressed('Ascend') ? 1 : 0) - (Input.pressed('Descend') ? 1 : 0)
    const s = this.speed * (Input.pressed('Sprint') ? this.sprintScale : 1)
    const want = [
      (fx * move[1] + rx * move[0]) * s,
      (fy * move[1] + lift) * s,
      (fz * move[1] + rz * move[0]) * s,
    ]
    const a = this.smoothing > 0 ? 1 - Math.exp(-delta / this.smoothing) : 1
    const v = this._velocity
    for (let i = 0; i < 3; i++) v[i] += (want[i] - v[i]) * a

    const p = this.position
    const next = [p[0] + v[0] * delta, p[1] + v[1] * delta, p[2] + v[2] * delta]
    const floor = this._groundAt(next[0], next[2]) + this.groundClearance
    if (next[1] < floor) {
      next[1] = floor
      if (v[1] < 0) v[1] = 0
    }
    this.setPosition(next as any)
  }

  /** The highest landscape under (x, z), world height; -Infinity where there is none. */
  private _groundAt(x: number, z: number): number {
    let best = -Infinity
    const landscapes: any = (this.scene as any)?.landscapes
    if (!landscapes) return best
    for (const l of landscapes) {
      const o = l.worldPosition
      const terrain = l.terrain
      if (!terrain) continue
      best = Math.max(best, o[1] + terrain.heightAt(x - o[0], z - o[2]))
    }
    return best
  }
}

import { Node } from 'cleo'

/**
 * Valley — a fire-and-forget effect: the pond's splashes. Attach to the root of an effect template. On
 * start it plays every Particle System below it, and removes the whole effect `lifetime` seconds later.
 *
 * The pond's Water Volume spawns these by template name (its Splash Template and Wade Splash Template).
 */
export default class ValleyFxNode extends Node {
  /** Seconds before the effect removes itself: at least as long as its longest particle lives. */
  public lifetime: number = 1.2

  private _age: number = 0

  onStart() {
    this._age = 0
    const walk = (node: Node) => {
      for (const child of node.children) {
        // play(), not restart(): a fresh instance is already playing if its system plays on start.
        if (child.nodeType === 'particleSystem') (child as any).play?.()
        walk(child)
      }
    }
    walk(this)
  }

  onUpdate(delta: number) {
    this._age += delta
    if (this._age >= this.lifetime) this.remove()
  }
}

import { Game, Input, InputSystem, Node, SequenceNode, UIButtonNode, UIRootNode } from 'cleo'

/**
 * The Valley — the start menu. Attach to the `Start Menu` node, a screen-space UI Root that is shown when
 * Play starts:
 *
 *   Backdrop
 *     Card
 *       Title        "The Valley"                              uiText
 *       Cinematic    plays the `Valley Tour` sequence          uiButton
 *       Free         flies the free camera (the Fly Camera)    uiButton
 *       Hint         the controls line                         uiText
 *
 * Up/Down (or the mouse) picks, Enter / Space / A confirms. Pause (P, Escape or Start) comes back here from
 * either mode: from the cinematic it stops the tour, which puts back everything the tour changed (the
 * camera, the sun). The tour coming to its end returns here too.
 *
 * The valley's day is the `Day Cycle` sequence (it plays by itself from the start, looping): under the menu
 * and through Free mode. The tour keys the sun itself, so the day is paused while it plays, and picks up again
 * where it was once the tour has put the sun back.
 *
 * It listens in a LATE UPDATE (`scene.addLateUpdate`), which runs every frame whatever the game is doing,
 * so the menu answers while the tour has the camera.
 *
 * Rendered to a movie from the editor (the Sequencer's Render), nobody is there to press a button:
 * `Game.movieRender` names what is filmed, and the menu goes straight into the tour, or out of the way.
 */
export default class ValleyStartMenuNode extends UIRootNode {
  /** The Sequence node the Cinematic button plays. */
  public tourName: string = 'Valley Tour'
  /** The Sequence node that runs the valley's day (paused while the tour has the sun). */
  public dayName: string = 'Day Cycle'
  /** Real seconds after the menu opens during which a confirm is ignored (the press that opened it). */
  public openGuard: number = 0.25
  public isOpen: boolean = false
  /** 'menu', 'cinematic' or 'free'. */
  public mode: string = 'menu'

  private _tour: SequenceNode = null
  private _day: SequenceNode = null
  private _buttons: UIButtonNode[] = []
  private _selected: number = 0
  private _navLast: number = 0
  private _clock: number = 0
  private _openedAt: number = 0
  private _stopListening: (() => void) | null = null
  private _stopFinished: (() => void) | null = null

  onStart() {
    this._tour = this.findNode(this.tourName) as SequenceNode
    this._day = this.findNode(this.dayName) as SequenceNode
    const cinematic = this._find('Cinematic') as UIButtonNode
    const free = this._find('Free') as UIButtonNode
    this._buttons = [cinematic, free].filter(b => !!b)
    if (cinematic) cinematic.onPress = () => this.playCinematic()
    if (free) free.onPress = () => this.playFree()
    this._stopFinished = this._tour?.onFinished(reason => { if (reason === 'finished') this._tourEnded() }) ?? null
    this._stopListening = this.scene?.addLateUpdate((_delta, unscaled) => this._listen(unscaled)) ?? null
    this.open()
    const movie = Game.movieRender
    if (movie && this._tour && movie.sequenceNodeId === this._tour.id) this.playCinematic()
    else if (movie) this._close('movie')
  }

  onDespawn() {
    this._stopListening?.()
    this._stopFinished?.()
    this._stopListening = this._stopFinished = null
  }

  /** Show the menu: no gameplay input, a free mouse. */
  public open(): void {
    this.isOpen = true
    this.mode = 'menu'
    this.visible = true
    this._openedAt = this._clock
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    InputSystem.instance.pointerLockOnClick = false
    this._refresh()
  }

  /** Play the tour from the start. */
  public playCinematic(): void {
    if (!this._tour) return
    this._close('cinematic')
    this._day?.pause()
    this._tour.play()
  }

  /** The tour is over (or left): its sun goes back to the day's, and the day goes on. */
  private _stopTour(): void {
    this._tour?.stop()
    if (this._day?.isPaused) this._day.resume()
  }

  /** Fly the free camera. */
  public playFree(): void {
    this._close('free')
    Input.enableMap('Gameplay')
    InputSystem.instance.pointerLockOnClick = true
  }

  private _close(mode: string): void {
    this.isOpen = false
    this.mode = mode
    this.visible = false
    Game.resume()
  }

  /** The tour ran to its end: put the valley back as it was and offer the choice again. */
  private _tourEnded(): void {
    this._stopTour()
    this.open()
  }

  private _listen(unscaled: number): void {
    this._clock += unscaled
    if (!this.isOpen) {
      if (!Input.started('Pause')) return
      if (this.mode === 'cinematic') this._stopTour()
      this.open()
      return
    }
    if (this._clock - this._openedAt < this.openGuard) return
    const nav = Input.vector('Navigate')
    const dy = Math.abs(nav[1]) > 0.5 ? Math.sign(nav[1]) : 0
    if (dy !== 0 && dy !== this._navLast && this._buttons.length > 0) {
      // Navigate Y is positive UP; the buttons run top to bottom.
      this._selected = (this._selected - dy + this._buttons.length) % this._buttons.length
      this._refresh()
    }
    this._navLast = dy
    if (Input.started('Submit')) this._buttons[this._selected]?.press()
  }

  /** The selected button lit, the other dim. */
  private _refresh(): void {
    this._buttons.forEach((b, i) => {
      b.tint = i === this._selected ? [0.36, 0.3, 0.2, 1] : [0.16, 0.14, 0.12, 1]
    })
  }

  private _find(name: string, under: Node = this): Node {
    for (const child of under.children) {
      if (child.name === name) return child
      const deeper = this._find(name, child)
      if (deeper) return deeper
    }
    return null
  }
}

import { SequenceNode } from 'cleo'
import type { SequenceScriptContext } from 'cleo'

/**
 * Valley — the tour's director: the script on the `Valley Tour` Sequence node. The tour's Script track calls its
 * methods over its sections (sequencer/types.ts ScriptSection), each with a SequenceScriptContext.
 *
 *   lightning   the storm's strikes: args [seed, strikes]
 *
 * LIGHTNING. Each strike is a few pulses a fraction of a second apart, each decaying over a tenth of a second,
 * from low in the clouds a few hundred metres off: an authored point light (`Lightning`, under the
 * Cinematic group) flashed to over half a trillion lumens (tens of thousands of lux on the ground, a storm's
 * daylight over again, for a fraction of a second, faster than the eye adapts), the clouds' ambient lit up with it. The schedule is drawn from the seed,
 * so where the timeline is decides the picture: a scrub or a seek shows the same flash a playback would. Never the sun: its change would relight the GI; the light is not baked, so neither the GI
 * nor the probes see it.
 */
export default class ValleyTourDirectorNode extends SequenceNode {
  /** The light the strikes flash, by name. */
  public lightningLight: string = 'Lightning'
  /** Lumens at a pulse's peak (written out in full: the editor's field reader takes no exponents). */
  public lightningLumens: number = 600000000000
  /** How much the clouds' ambient light rises at a peak, over its own. */
  public lightningClouds: number = 5

  private _light: any = null
  private _clouds: any = null
  private _ambient: number = 1
  private _strikes: { t: number, x: number, z: number, y: number }[] = []

  lightning(ctx: SequenceScriptContext) {
    if (ctx.phase === 'enter') {
      this._light = this.findNode(this.lightningLight)
      this._clouds = (this.scene as any)?.volumetricClouds ?? null
      this._ambient = this._clouds ? this._clouds.ambientIntensity : 1
      const [seed, strikes] = ctx.args as number[]
      this._strikes = this._schedule(Number(seed) || 1, Math.max(1, Number(strikes) || 6), ctx.duration)
    }
    const light = this._light
    if (ctx.phase === 'exit') {
      if (light?.light) light.light.intensity = 0
      if (this._clouds) this._clouds.ambientIntensity = this._ambient
      return
    }
    // The strike in charge: the last one started.
    let strike = null
    for (const s of this._strikes) if (s.t <= ctx.local) strike = s
    const flash = strike ? this._flash(ctx.local - strike.t) : 0
    if (light?.light) {
      light.light.intensity = this.lightningLumens * flash
      if (strike) {
        const eye = (this.scene as any)?.activeCamera?.worldPosition
        light.setPosition([(eye?.[0] ?? 0) + strike.x, strike.y, (eye?.[2] ?? 0) + strike.z])
      }
    }
    if (this._clouds) this._clouds.ambientIntensity = this._ambient * (1 + this.lightningClouds * flash)
  }

  /** `strikes` moments spread over `duration`, each with a spot in the clouds round the camera. */
  private _schedule(seed: number, strikes: number, duration: number) {
    let state = Math.floor(seed * 9301 + 49297) % 233280
    const rnd = () => { state = (state * 9301 + 49297) % 233280; return state / 233280 }
    const out: { t: number, x: number, z: number, y: number }[] = []
    for (let i = 0; i < strikes; i++) {
      const t = duration * (i + 0.15 + 0.7 * rnd()) / strikes
      const angle = rnd() * Math.PI * 2, distance = 100 + 200 * rnd()
      out.push({ t, x: Math.cos(angle) * distance, z: Math.sin(angle) * distance, y: 400 + 150 * rnd() })
    }
    return out
  }

  /** A strike's brightness `dt` seconds after it began: three pulses, each a fast rise and a 0.07 s decay, out by 0.5 s. */
  private _flash(dt: number): number {
    let f = 0
    for (const [at, peak] of [[0, 1], [0.09, 0.55], [0.22, 0.85]]) {
      const s = dt - at
      // Half a second on, a pulse is out (its tail would keep the light faintly on between strikes).
      if (s < 0 || s > 0.5) continue
      f = Math.max(f, peak * Math.min(1, s / 0.012) * Math.exp(-s / 0.07))
    }
    return f
  }
}
